// transcribe.py prints exactly one JSON object on stdout; its logs go to stderr
const { stdout, stderr, exitCode } = $input.first().json;
const last = String(stdout || '').trim().split(/\r?\n/).pop();
let result;
try {
  result = JSON.parse(last);
} catch (e) {
  throw new Error(`transcribe.py returned no JSON (exit ${exitCode}): ${String(stderr || '').slice(-400)}`);
}
if (!result.ok) throw new Error(`Transcription failed: ${result.error}`);

const slash = (p) => (p ? String(p).split('\\').join('/') : null);
return [{ json: { ...result, video_path: slash(result.video_path), thumbnail_path: slash(result.thumbnail_path), instructions_path: slash(result.instructions_path) } }];

