parameters.jsCode:
// Deterministic rules on top of the LLM output: YouTube limits, channel footer, tags.
const ai = $input.first().json.output;
const ch = $('Parse channel config').first().json.data;
const t = $('Parse transcript').first().json;

const oneLine = (s) => String(s ?? '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
const bytes = (s) => encodeURIComponent(s).replace(/%[0-9A-F]{2}/gi, 'x').length;

// Title: max 100 characters, no angle brackets (YouTube rejects them)
let title = oneLine(ai.title) || t.base_name;
if (title.length > 100) title = title.slice(0, 99).replace(/\s+\S*$/, '') + '…';

// Description: AI text + chapters (long videos only) + hashtags + channel footer, max 5000 bytes
const parts = [String(ai.description || '').replace(/[<>]/g, '').trim()];
const chapters = Array.isArray(ai.chapters) ? ai.chapters : [];
if (!t.is_short && chapters.length >= 3 && /^0?0:00$/.test(String(chapters[0].time).trim())) {
  parts.push(chapters.map((c) => `${String(c.time).trim()} ${oneLine(c.title)}`).join('\n'));
}
if (ch.hashtags?.length) parts.push(ch.hashtags.join(' '));
if (ch.description_footer) parts.push(ch.description_footer);
let description = parts.filter(Boolean).join('\n\n');
while (bytes(description) > 5000) description = description.slice(0, -50);

// Tags: channel defaults first, then AI tags; de-duplicated; YouTube counts quotes around
// tags with spaces and the commas between tags, total max 500 characters
const fold = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); // 'café' == 'cafe'
const tagList = [];
let budget = 0;
for (const raw of [...(ch.default_tags || []), ...(ai.tags || [])]) {
  const tag = oneLine(raw).replace(/[,#]/g, '').slice(0, 60);
  if (!tag || tagList.some((x) => fold(x) === fold(tag))) continue;
  const cost = tag.length + (tag.includes(' ') ? 2 : 0) + (tagList.length ? 1 : 0);
  if (budget + cost > 480) break;
  tagList.push(tag);
  budget += cost;
}

// Thumbnail text goes on a command line: keep letters, digits, spaces and simple punctuation
const thumbnailText = String(ai.thumbnail_text || title)
  .normalize('NFC')
  .replace(/[^\p{L}\p{N} ?!¿¡.,:'-]/gu, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 60) || 'NEW VIDEO';

return [{
  json: {
    channel: t.channel,
    channelName: ch.display_name || t.channel,
    fileName: t.file_name,
    baseName: String(t.base_name).replace(/[^A-Za-z0-9._-]+/g, '_'),
    videoPath: t.video_path,
    thumbnailPath: t.thumbnail_path,
    isShort: t.is_short,
    duration: t.duration_s,
    title,
    description,
    tagList,
    tags: tagList.join(','),
    thumbnailText,
    categoryId: String(ch.category_id || '22'),
    defaultLanguage: ch.metadata_language || 'en',
    madeForKids: Boolean(ch.made_for_kids),
  },
}];

const { stdout, stderr, exitCode } = $input.first().json;
let result;
try {
  result = JSON.parse(String(stdout || '').trim().split(/\r?\n/).pop());
} catch (e) {
  throw new Error(`thumbnail.py failed (exit ${exitCode}): ${String(stderr || '').slice(-400)}`);
}
if (!result.ok) throw new Error(`thumbnail.py failed: ${result.error}`);
return [{ json: { thumbFile: String(result.thumbnail_path).split('\\').join('/'), thumbSource: 'generated' } }];

// Texts for the Telegram preview (HTML) and the approval request (Telegram legacy Markdown)
const m = $('Apply channel rules').first().json;
const videoId = $('Upload to YouTube (private)').first().json.uploadId;
const thumb = $('Set custom thumbnail').first().json;
const thumbSource = $('Thumbnail ready').first().json.thumbSource;
const tr = $('Parse transcript').first().json;
const model = $env.OLLAMA_MODEL || 'gemma4:latest';
const instrFile = tr.instructions ? String(tr.instructions_path).split('/').pop() : null;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const md = (s) => String(s ?? '').replace(/([_*`\[])/g, '\\$1');
const studio = `https://studio.youtube.com/video/${videoId}/edit`;
const watch = `https://youtu.be/${videoId}`;
const thumbLine = thumb.error
  ? `${thumbSource} thumbnail NOT set on YouTube (channel not verified?)`
  : `${thumbSource} thumbnail set`;

const head = [
  `<b>${esc(m.title)}</b>`,
  `${esc(m.channelName)} · ${m.isShort ? 'Short' : 'Video'} · ${Math.round(m.duration)} s · uploaded as <b>private</b>`,
];
const tail = [
  `<i>Written by:</i> ${esc(model)} (local)${instrFile ? ` · instructions from ${esc(instrFile)}` : ''}`,
  `<i>Tags:</i> ${esc(m.tagList.slice(0, 12).join(', '))}`,
  `<i>Thumbnail:</i> ${esc(thumbLine)}`,
  `<a href="${studio}">Open in YouTube Studio</a> · <a href="${watch}">Watch</a>`,
];
// Telegram captions are limited to 1024 characters: the description gets what is left
const budget = 1000 - [...head, ...tail].join('\n').length - 4;
const desc = m.description.length > budget ? m.description.slice(0, Math.max(0, budget - 1)) + '…' : m.description;
const caption = [...head, '', esc(desc), '', ...tail].join('\n');

const titleHtml = `<b>${esc(m.title)}</b>`;
return [{
  json: {
    videoId,
    caption,
    approvalText: `*Publish this video?*\n${md(m.title)}\n\nCheck the preview above or in YouTube Studio. Publish makes it public now, Keep private leaves it visible only to you.`,
    publishedText: `✅ <b>Published</b>\n${titleHtml}\n${watch}`,
    lockedText: `⚠️ <b>YouTube kept the video private.</b>\n${titleHtml}\nUploads from API projects that have not passed YouTube's API audit stay private. Publish it by hand in Studio:\n${studio}`,
    failedText: `❌ <b>Could not publish</b>\n${titleHtml}\nThe video is still private. Studio: ${studio}`,
    keptText: `🔒 Kept private: ${titleHtml}`,
    timeoutText: `⌛ No decision within 48 h, kept private: ${titleHtml}\n${studio}`,
  },
}];

// One CSV line per run: timestamp,channel,file,video_id,title,outcome,detail,execution_id
const m = $('Apply channel rules').first().json;
const videoId = $('Upload to YouTube (private)').first().json.uploadId;
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };

let outcome;
let detail = '';
if (ran('Published')) {
  const status = $('Make public').first().json.status || {};
  outcome = status.privacyStatus === 'public' ? 'published' : 'publish_locked';
  detail = status.privacyStatus || '';
} else if (ran('Publish failed')) {
  outcome = 'publish_failed';
  const err = $('Make public').first().json.error;
  detail = (err && err.message) || String(err || '');
} else {
  outcome = $('Ask for approval').first().json.data ? 'declined' : 'no_answer';
}

const q = (v) => `"${String(v ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ')}"`;
const line = [new Date().toISOString(), m.channel, q(m.fileName), videoId, q(m.title), outcome, q(detail), $execution.id].join(',') + '\n';
return [{ json: { line, outcome } }];
